WITH parsed AS (SELECT id, service, host, level, status_code, payload_json, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, CAST((status_code & 1) != 0 AS INT) AS has_fault, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, context['region'] AS region, COALESCE(context['trace'], 'unknown') AS trace_or_default FROM app_logs) SELECT *, SUM(status_code) OVER w_hist AS service_sum_status_code, PERCENT_RANK() OVER (PARTITION BY service ORDER BY status_code DESC) AS status_code_percent_rank, STDDEV_SAMP(has_fault) OVER (PARTITION BY host) AS host_stddev_samp_has_fault, AVG(has_fault) OVER (ORDER BY retry_count, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS has_fault_avg_3, PERCENT_RANK() OVER (PARTITION BY host ORDER BY retry_count) AS retry_count_percent_rank FROM parsed WINDOW w_hist AS (PARTITION BY service);
